$env_node_path=$env:NODE_PATH
$new_node_path="F:\Projetos2026\DevMaster_Hermes\node_modules\.pnpm\tsup@8.5.1_tsx@4.23.15_typescript@7.0.2\node_modules\tsup\dist\node_modules;F:\Projetos2026\DevMaster_Hermes\node_modules\.pnpm\tsup@8.5.1_tsx@4.23.15_typescript@7.0.2\node_modules\tsup\node_modules;F:\Projetos2026\DevMaster_Hermes\node_modules\.pnpm\tsup@8.5.1_tsx@4.23.15_typescript@7.0.2\node_modules;F:\Projetos2026\DevMaster_Hermes\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/f/Projetos2026/DevMaster_Hermes/node_modules/.pnpm/tsup@8.5.1_tsx@4.23.15_typescript@7.0.2/node_modules/tsup/dist/node_modules:/mnt/f/Projetos2026/DevMaster_Hermes/node_modules/.pnpm/tsup@8.5.1_tsx@4.23.15_typescript@7.0.2/node_modules/tsup/node_modules:/mnt/f/Projetos2026/DevMaster_Hermes/node_modules/.pnpm/tsup@8.5.1_tsx@4.23.15_typescript@7.0.2/node_modules:/mnt/f/Projetos2026/DevMaster_Hermes/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
