  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../../dist/cli-default.js" $args
  } else {
    & "node$exe"  "$basedir/../../dist/cli-default.js" $args
  }
  $ret=$LASTEXITCODE
}
